package verify

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

// An ignored root falls back only when its tracked ordinary files are gone.
// Keep this observable through both copiers, their existing-code hash, and
// controls for roots that still belong to Git or require strict staging.
func TestDeletedTrackedStagingEvidence(t *testing.T) {
	gs391IsolateGit(t)
	rootWithDeleted := func(t *testing.T, ignored bool) (string, string) {
		t.Helper()
		repo := t.TempDir()
		gs391Init(t, repo)
		patterns := "*.cache\n"
		if ignored {
			patterns += "/package/\n"
		}
		writeFiles(t, repo, map[string]string{".gitignore": patterns, "package/src/deleted.ts": "old index bytes"})
		gs391Git(t, repo, "add", "-f", "package/src/deleted.ts")
		root := filepath.Join(repo, "package")
		if err := os.Remove(filepath.Join(root, "src", "deleted.ts")); err != nil {
			t.Fatal(err)
		}
		return repo, root
	}
	assertTree := func(t *testing.T, root string, want map[string]string) {
		t.Helper()
		if got := gs391Tree(t, root); !reflect.DeepEqual(got, want) {
			t.Errorf("staged bytes = %v, want %v", got, want)
		}
	}

	t.Run("ignored root copies current files", func(t *testing.T) {
		_, root := rootWithDeleted(t, true)
		want := map[string]string{
			"package.json": "{}", "package-lock.json": "{}", "tsconfig.json": "{}",
			"go.mod": "module example.invalid/fallback\n", "main.go": "package main\n",
			"src/keep.ts": "export const n = 1;", "src/local.cache": "included in directory mode",
			"unselected.txt": "outside the explicit existing boundary",
		}
		writeFiles(t, root, want)
		writeFiles(t, root, map[string]string{"bin/output": "excluded", "out/output": "excluded", "src/bin/output": "excluded", "src/out/output": "excluded"})
		copy := filepath.Join(t.TempDir(), "copy")
		if err := copyTree(root, copy); err != nil {
			t.Errorf("copyTree: %v", err)
		} else {
			assertTree(t, copy, want)
		}
		selected, err := stagingFiles(root, copyTreeExcluded, false)
		if err != nil || selected == nil || selected.Method != "directory" {
			t.Errorf("ignored root with only deleted tracked files: selection=%v, error=%v", selected, err)
		}
		pkg := filepath.Join(t.TempDir(), "package")
		if err := StagePackage(root, []string{"src"}, pkg); err != nil {
			t.Errorf("StagePackage refused fallback: %v", err)
		} else {
			assertTree(t, pkg, map[string]string{
				"package.json": "{}", "package-lock.json": "{}", "tsconfig.json": "{}",
				"src/keep.ts": want["src/keep.ts"], "src/local.cache": want["src/local.cache"],
			})
		}
		// Compute the receipt digest from the expected staged paths and bytes,
		// without using HashExisting itself to derive the expected value.
		h := sha256.New()
		for _, name := range []string{"src/keep.ts", "src/local.cache"} {
			fmt.Fprintf(h, "%s\n%d\n", name, len(want[name]))
			h.Write([]byte(want[name]))
		}
		hashes, err := HashExisting(root, []string{"src"})
		expected := []ExistingCode{{Path: "src", Files: 2, SHA256: "sha256:" + hex.EncodeToString(h.Sum(nil))}}
		if err != nil || !reflect.DeepEqual(hashes, expected) {
			t.Errorf("existing-code hash = %v, %v; want %v", hashes, err, expected)
		}
	})

	t.Run("surviving tracked file keeps Git selection", func(t *testing.T) {
		repo, root := rootWithDeleted(t, true)
		writeFiles(t, root, map[string]string{"live.go": "index bytes", "payload.cache": "ignored"})
		gs391Git(t, repo, "add", "-f", "package/live.go")
		writeFiles(t, root, map[string]string{"live.go": "working-tree bytes"})
		copy := filepath.Join(t.TempDir(), "copy")
		if err := copyTree(root, copy); err != nil {
			t.Fatal(err)
		}
		assertTree(t, copy, map[string]string{"live.go": "working-tree bytes"})
	})

	t.Run("nonignored root keeps Git selection", func(t *testing.T) {
		_, root := rootWithDeleted(t, false)
		writeFiles(t, root, map[string]string{"new.go": "package current\n", "payload.cache": "ignored"})
		copy := filepath.Join(t.TempDir(), "copy")
		if err := copyTree(root, copy); err != nil {
			t.Fatal(err)
		}
		assertTree(t, copy, map[string]string{"new.go": "package current\n"})
		selected, err := stagingFiles(root, copyTreeExcluded, false)
		if err != nil || selected == nil || selected.Method != "git" {
			t.Errorf("nonignored all-deleted root: selection=%v, error=%v", selected, err)
		}
	})

	t.Run("strict application still refuses ignored declarations", func(t *testing.T) {
		root, p := gs391Fixture(t)
		repo := filepath.Dir(root)
		gs391Init(t, repo)
		writeFiles(t, repo, map[string]string{".gitignore": "/application/\n", "application/deleted.py": "old bytes"})
		gs391Git(t, repo, "add", "-f", "application/deleted.py")
		if err := os.Remove(filepath.Join(root, "deleted.py")); err != nil {
			t.Fatal(err)
		}
		if err := stagingIgnored(root, []string{"acme/service/core.py"}, true); err == nil || !strings.Contains(err.Error(), "ignored by Git") {
			t.Errorf("strict declaration admitted: %v", err)
		}
		w, err := StagePythonApplication(pa310Load(t, p), filepath.Join(t.TempDir(), "stage"))
		if w != nil || err == nil || !strings.Contains(err.Error(), "ignored by Git") {
			t.Errorf("strict application root admitted: workspace=%v, error=%v", w, err)
		}
	})

	t.Run("missing gitlink still refused", func(t *testing.T) {
		repo, root := rootWithDeleted(t, true)
		gs391Git(t, repo, "add", ".gitignore")
		gs391Git(t, repo, "commit", "--quiet", "-m", "Ignored root fixture")
		head := gs391Git(t, repo, "rev-parse", "HEAD")
		gs391Git(t, repo, "update-index", "--add", "--cacheinfo", "160000,"+head+",package/vendor")
		writeFiles(t, root, map[string]string{"package.json": "{}", "package-lock.json": "{}", "payload.cache": "must not trigger fallback"})
		for _, copier := range []string{"copyTree", "StagePackage"} {
			dst := filepath.Join(t.TempDir(), "copy")
			var err error
			if copier == "copyTree" {
				err = copyTree(root, dst)
			} else {
				err = StagePackage(root, []string{"vendor"}, dst)
			}
			if err == nil || !strings.Contains(err.Error(), "vendor") || !strings.Contains(err.Error(), "submodule") {
				t.Errorf("%s failed to refuse an uninitialized gitlink by name: %v", copier, err)
			}
		}
	})
}

sources.internal/verify/python_snapshot_evidence:
package verify_test

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/receipt"
	"github.com/gitdek/invariant/internal/verify"
)

// The real public gate uses the existing local-Python transport fixture. The
// runner executes staged Python; only Docker transport and TLC are doubles.
// TypeScript preservation is part of this failing Python regression, since
// changing HashExisting globally would fix Python by breaking StagePackage.
func TestPythonSnapshotExistingEvidence(t *testing.T) {
	for _, mode := range []string{"directory", "git"} {
		t.Run(mode, func(t *testing.T) {
			pse400IsolateGit(t)
			tc, _ := pa327Fake(t)
			pse400TypeScriptHash(t, mode)
			f := pa327New(t, false, false)
			f.p.Manifest.Existing = []string{"tasks", "settings.py"}
			pa327Write(t, f.root, "settings.py", "VALUE = 23\n")
			pa327Write(t, f.root, "tasks/bin/tool.py", "def running():\n    return 'running'\n")
			pa327Write(t, f.root, "tasks/out/report.py", "def done():\n    return 'done'\n")
			pa327Write(t, f.root, "tasks/helper.py", "from .bin.tool import running\nfrom .out.report import done\ndef next_state(state):\n    return running() if state == 'pending' else done()\n")
			pa327Write(t, f.root, ".gitignore", "/tasks/ignored.py\n")
			pa327Write(t, f.root, "tasks/ignored.py", "IGNORED = True\n")
			pa327Write(t, f.root, "tasks/.venv/omitted.py", "NOT_STAGED = True\n")
			pa327Write(t, f.root, "tasks/__pycache__/omitted.py", "NOT_STAGED = True\n")
			pa327Save(t, f)
			if mode == "git" {
				pse400Git(t, f.root, "init", "--quiet")
				pse400Git(t, f.root, "add", "--all")
			}

			// Independently frame the actual staged bytes; never use HashExisting
			// as the Python oracle, since its directory exclusions are the bug.
			check := func() *verify.Report {
				t.Helper()
				w, err := verify.StagePythonApplication(f.p, filepath.Join(t.TempDir(), "snapshot"))
				if err != nil {
					t.Fatal(err)
				}
				if w.FileSelection != mode {
					t.Fatalf("snapshot selection = %q, want %q", w.FileSelection, mode)
				}
				want := make([]verify.ExistingCode, 0, len(f.p.Manifest.Existing))
				for _, selection := range f.p.Manifest.Existing {
					files := map[string][]byte{}
					for _, file := range w.Files {
						if file.Path == selection || strings.HasPrefix(file.Path, selection+"/") {
							body, err := os.ReadFile(filepath.Join(w.Root, filepath.FromSlash(file.Path)))
							if err != nil {
								t.Fatal(err)
							}
							files[file.Path] = body
						}
					}
					want = append(want, verify.ExistingCode{Path: selection, Files: len(files), SHA256: pse400Digest(files)})
				}
				taskFiles := 9
				if mode == "directory" {
					taskFiles++ // A directory snapshot retains ignored.py.
				}
				if want[0].Files != taskFiles || want[1].Files != 1 {
					t.Fatalf("unexpected staged fixture: %+v", want)
				}
				r := pa327Run(t, f, tc)
				pa327Assert(t, f, r, true)
				if !reflect.DeepEqual(r.Existing, want) {
					t.Errorf("Existing code must hash every staged file under each selection: got %+v, want %+v", r.Existing, want)
				}
				var wire struct {
					Existing []verify.ExistingCode `json:"existing"`
				}
				if err := json.Unmarshal(pa327JSON(t, r), &wire); err != nil {
					t.Fatal(err)
				}
				if !reflect.DeepEqual(wire.Existing, want) {
					t.Errorf("JSON existing evidence = %+v, want %+v", wire.Existing, want)
				}
				var row string
				for _, line := range strings.Split(receipt.Markdown(r), "\n") {
					if strings.HasPrefix(line, "| Existing code |") {
						row = line
					}
				}
				for _, code := range want {
					if !strings.Contains(row, code.Path) || !strings.Contains(row, fmt.Sprintf("%d file", code.Files)) || !strings.Contains(row, code.SHA256[:19]) {
						t.Errorf("Markdown Existing code row omits staged evidence %+v: %s", code, row)
					}
				}
				for _, execution := range r.Application.Executions {
					if execution.Provenance.FileSelection != mode || !reflect.DeepEqual(execution.Provenance.Files, w.Files) {
						t.Errorf("receipt provenance differs from the staged snapshot: %+v", execution.Provenance)
					}
				}
				return r
			}
			first := check()
			for _, name := range []string{"tasks/bin/tool.py", "tasks/out/report.py"} {
				body, err := os.ReadFile(filepath.Join(f.root, filepath.FromSlash(name)))
				if err != nil {
					t.Fatal(err)
				}
				pa327Write(t, f.root, name, string(body)+"# changed staged bytes\n")
				next := check()
				if first.Existing[0].SHA256 == next.Existing[0].SHA256 {
					t.Errorf("changing staged %s did not change the Existing code hash", name)
				}
				if !reflect.DeepEqual(first.Existing[1], next.Existing[1]) {
					t.Error("changing another selection changed the explicit file's receipt")
				}
				first = next
			}
		})
	}
}

func pse400Digest(files map[string][]byte) string {
	names := make([]string, 0, len(files))
	for name := range files {
		names = append(names, name)
	}
	sort.Strings(names)
	h := sha256.New()
	for _, name := range names {
		fmt.Fprintf(h, "%s\n%d\n", name, len(files[name]))
		h.Write(files[name])
	}
	return "sha256:" + hex.EncodeToString(h.Sum(nil))
}

func pse400TypeScriptHash(t *testing.T, mode string) {
	t.Helper()
	root := t.TempDir()
	for name, body := range map[string]string{
		"package.json": "{}", "package-lock.json": "{}",
		"lib/keep.ts": "export const kept = 1;\n", "lib/bin/tool.ts": "excluded bin bytes\n", "lib/out/report.ts": "excluded out bytes\n",
	} {
		pa327Write(t, root, name, body)
	}
	if mode == "git" {
		pse400Git(t, root, "init", "--quiet")
		pse400Git(t, root, "add", "--all")
	}
	want := []verify.ExistingCode{{Path: "lib", Files: 1, SHA256: pse400Digest(map[string][]byte{"lib/keep.ts": []byte("export const kept = 1;\n")})}}
	stage := filepath.Join(t.TempDir(), "package")
	if err := verify.StagePackage(root, []string{"lib"}, stage); err != nil {
		t.Fatal(err)
	}
	for _, name := range []string{"lib/bin/tool.ts", "lib/out/report.ts"} {
		if _, err := os.Stat(filepath.Join(stage, filepath.FromSlash(name))); !os.IsNotExist(err) {
			t.Errorf("TypeScript staged an excluded path %s: %v", name, err)
		}
	}
	for _, dir := range []string{root, stage} {
		got, err := verify.HashExisting(dir, []string{"lib"})
		if err != nil || !reflect.DeepEqual(got, want) {
			t.Errorf("TypeScript HashExisting changed its established package selection: got %+v, err %v, want %+v", got, err, want)
		}
	}
	pa327Write(t, root, "lib/bin/tool.ts", "changed excluded bin bytes\n")
	pa327Write(t, root, "lib/out/report.ts", "changed excluded out bytes\n")
	got, err := verify.HashExisting(root, []string{"lib"})
	if err != nil || !reflect.DeepEqual(got, want) {
		t.Errorf("excluded TypeScript changes altered its existing-code hash: got %+v, err %v, want %+v", got, err, want)
	}
}

func pse400IsolateGit(t *testing.T) {
	t.Helper()
	for _, key := range []string{"GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_COMMON_DIR", "GIT_OBJECT_DIRECTORY", "GIT_ALTERNATE_OBJECT_DIRECTORIES", "GIT_CONFIG_COUNT", "GIT_CONFIG_PARAMETERS"} {
		t.Setenv(key, "")
		if err := os.Unsetenv(key); err != nil {
			t.Fatal(err)
		}
	}
	t.Setenv("GIT_CONFIG_GLOBAL", os.DevNull)
	t.Setenv("GIT_CONFIG_NOSYSTEM", "1")
	t.Setenv("GIT_TERMINAL_PROMPT", "0")
}

func pse400Git(t *testing.T, root string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", append([]string{"-C", root}, args...)...)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git %v: %v\n%s", args, err, out)
	}
}

sources.internal/verify/staging_selection_receip:
package verify_test

// Issue #400 records selection evidence at the root each language stages:
// Go's module (which may be below the project), standalone TypeScript's
// project, and existing TypeScript's containing package. The public Report
// adds optional FileSelection, serialized as file_selection. Its values are
// git and directory, and Markdown explains git ls-files or whole directory.
// Model-only and old decoded reports with no evidence must not invent it.
//
// These tests exercise the real gate, copying, hashing, JSON and Markdown.
// Only Docker/verifier processes are doubled; the doubles inspect the staged
// files before returning tool results. No daemon, network or proof is needed.

import (
	"context"
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/receipt"
	"github.com/gitdek/invariant/internal/tla"
	"github.com/gitdek/invariant/internal/toolchain"
	"github.com/gitdek/invariant/internal/verify"
)

func se400Git(t *testing.T, root string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", append([]string{"-C", root}, args...)...)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git %v: %v\n%s", args, err, out)
	}
}

func se400IsolateGit(t *testing.T) {
	t.Helper()
	for _, name := range []string{"GIT_DIR", "GIT_WORK_TREE", "GIT_COMMON_DIR", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY", "GIT_ALTERNATE_OBJECT_DIRECTORIES", "GIT_CONFIG_COUNT", "GIT_CONFIG_PARAMETERS", "GIT_PREFIX", "GIT_CEILING_DIRECTORIES"} {
		t.Setenv(name, "")
		if err := os.Unsetenv(name); err != nil {
			t.Fatal(err)
		}
	}
	t.Setenv("GIT_CONFIG_GLOBAL", os.DevNull)
	t.Setenv("GIT_CONFIG_NOSYSTEM", "1")
	t.Setenv("GIT_TERMINAL_PROMPT", "0")
}

func se400Tools(t *testing.T) toolchain.Toolchain {
	t.Helper()
	bin := t.TempDir()
	assuranceWrite(t, bin, "go", "#!/bin/sh\necho 'go version go1.27.1 linux/amd64'\n", 0755)
	assuranceWrite(t, bin, "docker", `#!/bin/sh
if [ "$1" = image ] || [ "$1" = rm ]; then exit 0; fi
src= out= kind=
for arg in "$@"; do
  case "$arg" in
    *:/src) src=${arg%:/src} ;;
    *:/out) out=${arg%:/out} ;;
    selection400-java) kind=java ;;
    selection400-gobra) kind=gobra ;;
    selection400-go) kind=go ;;
    selection400-node) kind=node ;;
    invariant-deps:*) kind=existing ;;
  esac
done
case "$kind" in
  java)
    cat <<'TLC'
@!@!@STARTMSG 2193:0 @!@!@
Model checking completed. No error has been found.
@!@!@ENDMSG 2193 @!@!@
@!@!@STARTMSG 2199:0 @!@!@
1 states generated, 1 distinct states found, 0 states left on queue.
@!@!@ENDMSG 2199 @!@!@
@!@!@STARTMSG 2194:0 @!@!@
The depth of the complete state graph search is 1.
@!@!@ENDMSG 2194 @!@!@
TLC
    exit 0 ;;
  gobra) echo 'Gobra found 0 errors'; exit 0 ;;
  go) required=core.go; cache=local.cache; [ -f "$src/go.mod" ] || exit 81 ;;
  node) required=core.js; cache=local.cache ;;
  existing) required=src/lib/core.js; cache=src/lib/local.cache; [ -f "$src/package-lock.json" ] || exit 82 ;;
  *) echo 'unexpected tool invocation' >&2; exit 83 ;;
esac
[ -f "$src/$required" ] || { echo 'required source was not staged' >&2; exit 84; }
if [ "$SE400_SELECTION" = git ]; then
  [ ! -e "$src/$cache" ] || exit 85
else
  [ -f "$src/$cache" ] || { echo 'directory selection omitted payload' >&2; exit 86; }
fi
case "$kind" in
  go) printf '@@invariant vet=0\n@@invariant test=0\ninvariant-agreement states=1 depth=1\n@@invariant agree=0\n' ;;
  node|existing)
    printf '{"traces":[[{"n":0},{"n":0}]]}' > "$out/traces.json"
    if [ "$kind" = node ]; then printf '@@invariant test=0\n'; fi
    printf '@@invariant conform=0\n' ;;
esac
`, 0755)
	t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH"))
	return toolchain.Toolchain{JavaImage: "selection400-java", GobraImage: "selection400-gobra", GoImage: "selection400-go", NodeImage: "selection400-node", TLCJar: filepath.Join(bin, "tla.jar")}
}

func se400Fixture(t *testing.T, kind, mode string) (dir, stagingRoot string, existing []verify.ExistingCode) {
	t.Helper()
	outer := t.TempDir()
	dir = filepath.Join(outer, "project")
	stagingRoot = dir
	language, code, driver := "typescript", ".", "driver.js"
	var selections []string
	switch kind {
	case "go":
		language, code, driver = "go", "implementation", ""
		stagingRoot = filepath.Join(dir, code)
		assuranceWrite(t, stagingRoot, "go.mod", "module example.test/selection\n\ngo 1.27.1\n", 0644)
		assuranceWrite(t, stagingRoot, "core.go", "package core\ntype State int\nfunc Init() State { return 0 }\nfunc Successors(State) []State { return nil }\n", 0644)
		assuranceWrite(t, stagingRoot, "local.cache", "directory payload\n", 0644)
	case "typescript":
		assuranceWrite(t, dir, "core.js", "export const n = 0;\n", 0644)
		assuranceWrite(t, dir, driver, "import { n } from './core.js';\n", 0644)
		assuranceWrite(t, dir, "local.cache", "directory payload\n", 0644)
	case "existing-typescript":
		stagingRoot = filepath.Join(outer, "package")
		dir = filepath.Join(stagingRoot, "verification", "check")
		selections = []string{"src/lib"}
		assuranceWrite(t, stagingRoot, "package.json", `{"name":"selection","type":"module"}`, 0644)
		assuranceWrite(t, stagingRoot, "package-lock.json", `{"lockfileVersion":3}`, 0644)
		assuranceWrite(t, stagingRoot, "src/lib/core.js", "export const n = 0;\n", 0644)
		assuranceWrite(t, stagingRoot, "src/lib/local.cache", "directory payload\n", 0644)
		assuranceWrite(t, dir, driver, "import { n } from '../../src/lib/core.js';\n", 0644)
	default:
		t.Fatalf("unknown fixture kind %s", kind)
	}
	src := "---- MODULE Selection ----\nEXTENDS Naturals\nCONSTANT Limit\nVARIABLE n\nvars == <<n>>\nInit == n = 0\nNext == n' = n\nSpec == Init /\\ [][Next]_vars\nSafe == n = 0 /\\ n <= Limit\n====\n"
	statements := []project.Statement{{Name: "Spec", Kind: project.Spec}, {Name: "Safe", Kind: project.Invariant}}
	for i := range statements {
		h, err := tla.PinHash(src, statements[i].Name, project.Model)
		if err != nil {
			t.Fatal(err)
		}
		statements[i].SHA256 = h
	}
	manifest := project.Manifest{Name: "selection evidence", Language: language, Code: code, Module: ".invariant/specs/Selection.tla", Conformance: driver, Existing: selections}
	lock := project.Lock{Decision: "selection-fixture-only", Bounds: map[string]string{"Limit": "1"}, Statements: statements}
	for name, value := range map[string]any{".invariant/invariant.json": manifest, ".invariant/ratified.lock": lock} {
		data, err := json.Marshal(value)
		if err != nil {
			t.Fatal(err)
		}
		assuranceWrite(t, dir, name, string(data), 0644)
	}
	assuranceWrite(t, dir, ".invariant/specs/Selection.tla", src, 0644)
	if mode != "directory" {
		se400Git(t, outer, "init", "--quiet")
		if mode == "git" {
			assuranceWrite(t, outer, ".gitignore", "*.cache\n", 0644)
			se400Git(t, outer, "add", "--all")
		} else {
			// Keep the project's model visible; for Go only its nested module
			// is ignored. Inferring selection from p.Dir would say git here.
			rel, err := filepath.Rel(outer, stagingRoot)
			if err != nil {
				t.Fatal(err)
			}
			assuranceWrite(t, outer, ".gitignore", "/"+filepath.ToSlash(rel)+"/\n", 0644)
			assuranceWrite(t, stagingRoot, "retired.txt", "indexed then deleted\n", 0644)
			se400Git(t, outer, "add", "-f", filepath.ToSlash(filepath.Join(rel, "retired.txt")))
			if err := os.Remove(filepath.Join(stagingRoot, "retired.txt")); err != nil {
				t.Fatal(err)
			}
		}
	}
	// Expected TypeScript digest comes from a directory with exactly the
	// files StagePackage must copy, independent of the report's calculation.
	if kind == "existing-typescript" {
		expected := t.TempDir()
		assuranceWrite(t, expected, "src/lib/core.js", "export const n = 0;\n", 0644)
		if mode != "git" {
			assuranceWrite(t, expected, "src/lib/local.cache", "directory payload\n", 0644)
		}
		var err error
		existing, err = verify.HashExisting(expected, selections)
		if err != nil {
			t.Fatal(err)
		}
	}
	return dir, stagingRoot, existing
}

func se400Receipt(t *testing.T, kind string) {
	t.Helper()
	se400IsolateGit(t)
	tc := se400Tools(t)
	for _, mode := range []string{"git", "directory", "ignored-deleted"} {
		t.Run(mode, func(t *testing.T) {
			want := mode
			if mode == "ignored-deleted" {
				want = "directory"
			}
			t.Setenv("SE400_SELECTION", want)
			dir, _, existing := se400Fixture(t, kind, mode)
			ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
			defer cancel()
			r, err := verify.Run(ctx, dir, "", tc)
			if err != nil || r == nil {
				t.Fatalf("gate did not return a receipt: %v", err)
			}
			if !r.Passed || !r.Build.Passed || !r.Design.Passed {
				t.Fatalf("fixture did not finish its checks: %+v", r)
			}
			if !reflect.DeepEqual(r.Existing, existing) {
				t.Errorf("existing-code digest = %+v, want %+v", r.Existing, existing)
			}
			data, err := json.Marshal(r)
			if err != nil {
				t.Fatal(err)
			}
			var fields map[string]json.RawMessage
			if err := json.Unmarshal(data, &fields); err != nil {
				t.Fatal(err)
			}
			if string(fields["file_selection"]) != `"`+want+`"` {
				t.Errorf("receipt file_selection = %s, want %q", fields["file_selection"], want)
			}
			phrase := "git ls-files"
			if want == "directory" {
				phrase = "whole directory"
			}
			var decoded verify.Report
			if err := json.Unmarshal(data, &decoded); err != nil {
				t.Fatal(err)
			}
			for _, report := range []*verify.Report{r, &decoded} {
				if markdown := strings.ToLower(receipt.Markdown(report)); !strings.Contains(markdown, phrase) {
					t.Errorf("Markdown does not explain %q selection:\n%s", want, markdown)
				}
			}
			if r.Fingerprint != verify.Fingerprint(*r) || verify.Fingerprint(decoded) != r.Fingerprint {
				t.Error("fingerprint was not finalized with portable selection evidence")
			}
			other := "directory"
			if want == "directory" {
				other = "git"
			}
			fields["file_selection"] = json.RawMessage(`"` + other + `"`)
			changed, err := json.Marshal(fields)
			if err != nil {
				t.Fatal(err)
			}
			var changedReport verify.Report
			if err := json.Unmarshal(changed, &changedReport); err != nil {
				t.Fatal(err)
			}
			if verify.Fingerprint(changedReport) == r.Fingerprint {
				t.Error("fingerprint does not bind file_selection")
			}
			delete(fields, "file_selection")
			oldJSON, err := json.Marshal(fields)
			if err != nil {
				t.Fatal(err)
			}
			var oldReport verify.Report
			if err := json.Unmarshal(oldJSON, &oldReport); err != nil {
				t.Fatal(err)
			}
			oldMarkdown := strings.ToLower(receipt.Markdown(&oldReport))
			if strings.Contains(oldMarkdown, "git ls-files") || strings.Contains(oldMarkdown, "whole directory") {
				t.Error("an old receipt without selection evidence invented a method")
			}
			model, err := verify.RunModel(ctx, dir, tc)
			if err != nil || model == nil || !model.Passed {
				t.Fatalf("model-only fixture: %v", err)
			}
			modelJSON, err := json.Marshal(model)
			if err != nil {
				t.Fatal(err)
			}
			if strings.Contains(string(modelJSON), `"file_selection"`) {
				t.Error("model-only receipt invented a code selection")
			}
		})
	}
}

